#nullable enable // autogenerated

using MukioI18n;
using MVZ2.GameContent.Contraptions;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Definitions;
using MVZ2.Vanilla.Localization;
using MVZ2.Vanilla.RandomChina;
using MVZ2Logic.Entities;
using MVZ2Logic.Grids;
using PVZEngine.Entities;
using PVZEngine.Tools.Random;

namespace MVZ2.GameContent.RandomChinaEvents
{
    [RandomChinaEventDefinition(VanillaRandomChinaEventNames.toTheMoon)]
    public class ToTheMoonEvent : RandomChinaEventDefinition
    {
        public ToTheMoonEvent(string nsp, string path) : base(nsp, path, NAME, DESCRIPTION)
        {
        }
        public override void Run(Entity contraption, RandomGenerator rng)
        {
            var level = contraption.Level;
            var tile = contraption.GetGrid();
            if (tile != null && tile.CanSpawnEntity(VanillaContraptionID.antiGravityPad))
            {
                tile.SpawnPlacedEntity(VanillaContraptionID.antiGravityPad);
                contraption.PlaySound(VanillaSoundID.finalItem);
            }
        }
        [TranslateMsg("随机瓷器事件名称", VanillaStrings.CONTEXT_RANDOM_CHINA_EVENT_NAME)]
        public const string NAME = "去月球";
        [TranslateMsg("随机瓷器事件描述", VanillaStrings.CONTEXT_RANDOM_CHINA_EVENT_DESCRIPTION)]
        public const string DESCRIPTION = "生成反重力板";
    }
}
